/**
 * Unit tests for TokenBuffer.writeNumber(int).
 */
public class TokenBuffer_writeNumber_TriageGen0Test {

    private ObjectMapper mapper;

    @Before
    public void setUp() {
        mapper = new ObjectMapper();
    }











    @Test
    public void testWriteNumber_MultipleValues() throws IOException {
        TokenBuffer buffer = new TokenBuffer(mapper);

        buffer.writeNumber(10);
        buffer.writeNumber(20);

        JsonParser parser = buffer.asParser();

        Assert.assertEquals(JsonToken.VALUE_NUMBER_INT, parser.nextToken());
        Assert.assertEquals(10, parser.getIntValue());

        Assert.assertEquals(JsonToken.VALUE_NUMBER_INT, parser.nextToken());
        Assert.assertEquals(20, parser.getIntValue());

        Assert.assertNull(parser.nextToken());
    }
}
